package com.hbm.client.excavator;
import com.hbm.client.gui.LegacyContainerScreen;import com.hbm.fluid.FluidTank;import com.hbm.item.battery.BatteryItem;import com.hbm.item.fluid.client.FluidInfo;import com.hbm.machine.excavator.*;import java.util.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.resources.sounds.SimpleSoundInstance;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.player.Inventory;import net.neoforged.neoforge.network.PacketDistributor;
/** Exact242x204 source: separated top/bottom backgrounds and five original40px lever hitboxes. */
public final class ExcavatorScreen extends LegacyContainerScreen<ExcavatorMenu> {
 private static final String[] KEYS={"drill","crusher","walling","veinminer","silktouch"};public ExcavatorScreen(ExcavatorMenu menu,Inventory inv,Component title){super(menu,inv,title,ExcavatorContent.id("textures/gui/machine/gui_mining_drill.png"),242,204);}private ExcavatorBlockEntity machine(){return minecraft!=null&&minecraft.level!=null&&minecraft.level.getBlockEntity(menu.position()) instanceof ExcavatorBlockEntity machine?machine:null;}
 @Override protected void renderLabels(GuiGraphics g,int x,int y){g.drawString(font,playerInventoryTitle,41,110,4210752,false);}
 @Override protected void renderBg(GuiGraphics g,float partial,int x,int y){g.setColor(1,1,1,1);drawLegacyRegion(g,0,0,0,0,242,96);drawLegacyRegion(g,33,104,33,104,176,100);var m=machine();if(m==null)return;int height=(int)(m.power*52/ExcavatorBlockEntity.MAX_POWER);drawLegacyRegion(g,220,70-height,229,156-height,16,height);if(m.power>m.consumption)drawLegacyRegion(g,224,4,239,156,9,12);boolean blink=System.currentTimeMillis()%1000<500;if(m.drill()==null&&blink)drawLegacyRegion(g,171,74,209,154,18,18);boolean[] enabled={m.enableDrill,m.enableCrusher,m.enableWalling,m.enableVeinMiner,m.enableSilkTouch};for(int i=0;i<5;i++)if(enabled[i]){drawLegacyRegion(g,6+i*24,42,209,114,20,40);boolean valid=i==0?m.drill()!=null&&m.power>=m.consumption:i==3?m.canVeinMine():i!=4||m.canSilkTouch();if(valid||blink)drawLegacyRegion(g,11+i*24,5,valid?209:219,104,10,10);}tank(g,m.tank);}
 private void tank(GuiGraphics g,FluidTank tank){int remaining=tank.getFill()*52/tank.getMaxFill(),color=tank.getTankType().getTint();g.setColor((color>>16&255)/255F,(color>>8&255)/255F,(color&255)/255F,1);int bottom=70;while(remaining>0){int height=Math.min(remaining,16);g.blit(tank.getTankType().getTexture(),leftPos+202,topPos+bottom-height,0,16-height,16,height,16,16);remaining-=height;bottom-=height;}g.setColor(1,1,1,1);}
 @Override public void render(GuiGraphics g,int x,int y,float partial){super.render(g,x,y,partial);for(int i=0;i<5;i++)if(legacyInfoHovered(x,y,6+i*24,42,20,40))g.renderTooltip(font,Component.translatable("excavator."+KEYS[i]),x,y);var m=machine();if(m==null)return;if(legacyInfoHovered(x,y,220,18,16,52))g.renderTooltip(font,Component.literal(BatteryItem.shortNumber(m.power)+"/"+BatteryItem.shortNumber(ExcavatorBlockEntity.MAX_POWER)+"HE"),x,y);if(legacyInfoHovered(x,y,202,18,16,52)){var lines=new ArrayList<Component>();lines.add(m.tank.getTankType().displayName());lines.add(Component.literal(m.tank.getFill()+"/"+m.tank.getMaxFill()+"mB"));FluidInfo.append(m.tank.getTankType(),lines,hasShiftDown());g.renderComponentTooltip(font,lines,x,y);}}
 @Override public boolean mouseClicked(double x,double y,int button){boolean result=super.mouseClicked(x,y,button);for(int i=0;i<5;i++)if(legacyInfoHovered(x,y,6+i*24,42,20,40)){minecraft.getSoundManager().play(SimpleSoundInstance.forUI(com.hbm.registry.HbmSounds.get("hbm:block.leverLarge"),1));PacketDistributor.sendToServer(new ExcavatorControl(menu.position(),KEYS[i]));return true;}return result;}
}
